CREATE TABLE public.documents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  title text NOT NULL,
  category text NOT NULL,
  source_name text NOT NULL,
  source_url text NOT NULL,
  content text NOT NULL,
  search_vector tsvector GENERATED ALWAYS AS (to_tsvector('simple', title || ' ' || content)) STORED,
  created_at timestamptz NOT NULL DEFAULT now()
);

GRANT SELECT ON public.documents TO anon, authenticated;
GRANT ALL ON public.documents TO service_role;

ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Anyone can read documents" ON public.documents FOR SELECT TO anon, authenticated USING (true);

CREATE INDEX documents_search_idx ON public.documents USING gin (search_vector);

-- Keyword search: splits the question into words, keeps the first 5 letters of each
-- word (a very simple "stemmer" so "пасош", "пасошот", "пасоши" all match), and ranks documents.
CREATE OR REPLACE FUNCTION public.search_documents(query text, match_count int DEFAULT 4)
RETURNS TABLE (id uuid, title text, category text, source_name text, source_url text, content text, rank real)
LANGUAGE sql STABLE
SET search_path = public
AS $$
  WITH words AS (
    SELECT DISTINCT left(w, 5) AS w
    FROM regexp_split_to_table(lower(query), '[^а-яѓќѕљњџјa-z0-9]+') AS w
    WHERE length(w) >= 3
  ),
  q AS (
    SELECT to_tsquery('simple', string_agg(w || ':*', ' | ')) AS tsq FROM words
  )
  SELECT d.id, d.title, d.category, d.source_name, d.source_url, d.content,
         ts_rank(d.search_vector, q.tsq) AS rank
  FROM public.documents d, q
  WHERE q.tsq IS NOT NULL AND d.search_vector @@ q.tsq
  ORDER BY rank DESC
  LIMIT match_count;
$$;

GRANT EXECUTE ON FUNCTION public.search_documents(text, int) TO anon, authenticated, service_role;

INSERT INTO public.documents (title, category, source_name, source_url, content) VALUES
('Вадење лична карта', 'Лични документи', 'Министерство за внатрешни работи', 'https://mvr.gov.mk',
'Личната карта е задолжителна за секој државјанин на Република Северна Македонија над 18 години со живеалиште во државата. Барањето се поднесува лично во подрачната единица на МВР според местото на живеење. Потребни документи: пополнет образец за барање, извод од матична книга на родените (доколку податоците не се во електронскиот регистар), уверение за државјанство (се проверува по службена должност), доказ за платена административна такса и стара лична карта при замена. При поднесување се фотографира и се земаат отпечатоци од прсти. Рок за изработка: до 15 дена во редовна постапка; постои и итна постапка со повисока такса. Важност: 10 години за полнолетни лица. Губење или кражба мора да се пријави веднаш во полиција.'),
('Вадење патна исправа (пасош)', 'Лични документи', 'Министерство за внатрешни работи', 'https://mvr.gov.mk',
'Пасош (патна исправа) може да извади секој државјанин на Република Северна Македонија. Барањето се поднесува лично во подрачната единица на МВР. За малолетни лица барањето го поднесуваат родителите или старателот, со согласност од двајцата родители. Потребни документи: важечка лична карта (за полнолетни), извод од матична книга на родените за малолетни, доказ за уплатена такса за образец и административна такса, стар пасош доколку постои. Рок за изработка: до 15 дена во редовна постапка, итна постапка до 3 работни дена. Важност: 10 години за полнолетни, 5 години за деца над 4 години и 2 години за деца до 4 години.'),
('Пријавување во Агенција за вработување како невработено лице', 'Вработување', 'Агенција за вработување на РСМ', 'https://av.gov.mk',
'Невработено лице може да се пријави во центарот за вработување според местото на живеење. Услови: лицето е на возраст од 15 до 64 години, способно и подготвено да работи, не е во работен однос и активно бара работа. Потребни документи: важечка лична карта и доказ за образование (диплома или свидетелство). Пријавувањето може да се започне и електронски преку порталот на Агенцијата. По пријавувањето, лицето добива индивидуален план за вработување и треба редовно да се јавува во центарот (најмалку еднаш на 60 дена). Пријавените лица можат да учествуваат во оперативните планови за активни мерки: обуки, стажирање, субвенционирано вработување и самовработување.'),
('Паричен надоместок во случај на невработеност', 'Вработување', 'Агенција за вработување на РСМ', 'https://av.gov.mk',
'Право на паричен надоместок има невработено лице кое било осигурено најмалку 9 месеци непрекинато или 12 месеци со прекин во последните 18 месеци, а работниот однос му престанал без негова волја (на пример стечај, технолошки вишок, истек на договор на определено време). Барањето се поднесува во центарот за вработување во рок од 30 дена од престанокот на работниот однос. Потребни документи: лична карта, решение или одлука за престанок на работниот однос, М1/М2 образец (се проверува електронски). Надоместокот изнесува 50% од просечната нето плата на лицето во последните 24 месеци, а траењето зависи од стажот (од 1 месец до 12 месеци, подолго за постари лица со долг стаж).'),
('Гарантирана минимална помош', 'Социјални услуги', 'Министерство за социјална политика, демографија и млади', 'https://www.mtsp.gov.mk',
'Гарантираната минимална помош е парична помош за домаќинства без доволно приходи за основни потреби. Право има домаќинство чии вкупни приходи се пониски од утврдениот износ на гарантирана минимална помош, а членовите способни за работа се пријавени како невработени во Агенцијата за вработување. Барањето се поднесува во Центарот за социјална работа според местото на живеење. Потребни документи: барање (образец), лични карти за членовите, изјава за членовите на домаќинството, докази за приходи и имот (дел се проверуваат по службена должност). Центарот одлучува со решение најдоцна во рок од 30 дена. Корисниците имаат право и на здравствено осигурување и на енергетски додаток во зимските месеци.'),
('Детски додаток', 'Социјални услуги', 'Министерство за социјална политика, демографија и млади', 'https://www.mtsp.gov.mk',
'Детски додаток е парично право за дете до 18-годишна возраст (или до 26 години доколку е на редовно образование) кое живее во домаќинство со ниски приходи. Барањето го поднесува родител или старател во Центарот за социјална работа или електронски. Услови: родителот е државјанин и има живеалиште во државата, детето редовно ги посетува задолжителните вакцинации и образованието, приходите на домаќинството се под утврдениот праг. Потребни документи: барање, извод од матична книга на родените за детето, лична карта на родителот, потврда за редовно школување за деца над 15 години, доказ за приходи. Износот зависи од возраста на детето.'),
('Запишување на државен универзитет', 'Образование', 'Министерство за образование и наука', 'https://mon.gov.mk',
'Запишувањето на прв циклус студии на државните универзитети (на пр. УКИМ Скопје, УКЛО Битола, УГД Штип) се врши врз основа на конкурс што се објавува секоја пролет. Услови: завршено четиригодишно средно образование и положена државна матура (или училишна матура за определени студиски програми). Потребни документи: пријава за запишување (електронски преку порталот на универзитетот), свидетелства од I до IV година, диплома за положена матура, извод од матична книга на родените, лична карта и доказ за уплата на пријавен надоместок. Рангирањето се врши според успехот од средно училиште и матурата. Студентите во државна квота плаќаат партиципација од 200 евра годишно.'),
('Сместување во студентски дом и стипендии', 'Образование', 'Министерство за образование и наука', 'https://mon.gov.mk',
'Редовните студенти на државни универзитети кои студираат надвор од местото на живеење можат да аплицираат за сместување во државен студентски дом. Конкурсот се објавува во летото, пред почетокот на академската година. Предност имаат студенти со подобар успех и студенти од семејства со ниски приходи. Потребни документи: пријава, потврда за запишан семестар, уверение за просечен успех, лична карта, доказ за приходи на семејството. Министерството објавува и конкурс за државни стипендии: за успешни студенти (просек над 8,5), за студенти со социјален ризик, за студенти со попреченост и за студенти на дефицитарни студиски програми. Стипендијата се исплаќа месечно во текот на академската година.'),
('Регистрирање на трговец поединец или ДООЕЛ', 'Вработување', 'Централен регистар на РСМ', 'https://www.crm.com.mk',
'Регистрацијата на нов бизнис (трговец поединец, ДООЕЛ или ДОО) се врши во Централниот регистар, лично на шалтер или електронски преку системот за е-регистрација. Регистрацијата се врши по принцип на едношалтерски систем и трае до 4 часа. Потребни документи: лична карта на основачот/управителот, изјава/одлука за основање, назив на субјектот и седиште, приоритетна дејност. За ДООЕЛ и ДОО минималниот основачки влог е 5.000 евра во денарска противвредност (може да се уплати и подоцна во законски рок). По регистрацијата, субјектот автоматски добива ЕМБС и даночен број. Невработени лица можат да бараат грант за самовработување од Агенцијата за вработување пред регистрацијата.');